/// <reference types="node" />
// Calendar regression suite generated from fixtures/large5/calendar_regression/cases.json (synthetic).
// Drop next to mobile/src/lib/calendar.ts and run with Node >= 20.6 through a TS loader, e.g.
//   ../server/node_modules/.bin/tsx --test src/lib/calendar.regression.test.ts   (from mobile/)
// expo-calendar / react-native are replaced by in-memory fakes via node:module register() hooks, so no device or Expo runtime is needed.
// The former known gaps (busy all-day events block meals; prefer the first gap >= 60 min, else the longest gap) are fixed in
// calendar.ts and run as normal tests alongside the controls.
// Each case sets process.env.TZ (Node re-reads it on assignment) because meal windows are device-local.
import assert from "node:assert/strict";
import { createRequire, register } from "node:module";
import { before, describe, test } from "node:test";

type Ev = { startDate: string; endDate: string; allDay: boolean; availability: string };
type Win = { start: string; minutes: number; meal: "lunch" | "dinner" };
type Case = { id: string; tz: string; now: string; days: number; access: "granted" | "denied" | "read_error"; events: Ev[]; expected: Win[] };

const FAKES: Record<string, string> = {
  "expo-calendar": `const C = () => globalThis.__fakeCalendar;
export const EntityTypes = { EVENT: "event" };
export const Availability = { FREE: "free", BUSY: "busy", TENTATIVE: "tentative", UNAVAILABLE: "unavailable", NOT_SUPPORTED: "notSupported" };
export const getCalendarPermissions = (...a) => C().getCalendarPermissions(...a);
export const requestCalendarPermissions = (...a) => C().requestCalendarPermissions(...a);
export const getCalendars = (...a) => C().getCalendars(...a);
export const listEvents = (...a) => C().listEvents(...a);
export const getDefaultCalendarSync = () => null;`,
  "expo-calendar/legacy": `export const createEventAsync = async () => "fake-event"; export const updateEventAsync = async () => {};`,
  "react-native": `export const Platform = { OS: "ios" };`,
};
const HOOKS = `const FAKES = ${JSON.stringify(FAKES)};
export async function resolve(s, c, next) { return s in FAKES ? { url: "miple-fake:" + encodeURIComponent(s), shortCircuit: true } : next(s, c); }
export async function load(u, c, next) { return u.startsWith("miple-fake:") ? { format: "module", source: FAKES[decodeURIComponent(u.slice(11))], shortCircuit: true } : next(u, c); }`;
register("data:text/javascript," + encodeURIComponent(HOOKS), import.meta.url);

// Under tsx the mobile package loads as CommonJS, where the ESM hooks above never run: fake require() too.
const C = () => (globalThis as any).__fakeCalendar;
const CJS_FAKES: Record<string, unknown> = {
  "expo-calendar": {
    EntityTypes: { EVENT: "event" },
    Availability: { FREE: "free", BUSY: "busy", TENTATIVE: "tentative", UNAVAILABLE: "unavailable", NOT_SUPPORTED: "notSupported" },
    getCalendarPermissions: (...a: unknown[]) => C().getCalendarPermissions(...a),
    requestCalendarPermissions: (...a: unknown[]) => C().requestCalendarPermissions(...a),
    getCalendars: (...a: unknown[]) => C().getCalendars(...a),
    listEvents: (...a: unknown[]) => C().listEvents(...a),
    getDefaultCalendarSync: () => null,
  },
  "expo-calendar/legacy": { createEventAsync: async () => "fake-event", updateEventAsync: async () => {} },
  "react-native": { Platform: { OS: "ios" } },
};
const NodeModule = createRequire(import.meta.url)("node:module");
const originalLoad = NodeModule._load;
NodeModule._load = function (request: string, ...rest: unknown[]) {
  return request in CJS_FAKES ? CJS_FAKES[request] : originalLoad.call(this, request, ...rest);
};

let findFreeMealWindows: (days?: number, now?: Date) => Promise<{ start: Date; end: Date; minutes: number; meal: string }[]>;
before(async () => { ({ findFreeMealWindows } = await import("./calendar.js")); });

async function run(c: Case): Promise<Win[]> {
  process.env.TZ = c.tz;
  (globalThis as any).__fakeCalendar = {
    getCalendarPermissions: async () => ({ granted: c.access !== "denied" }),
    requestCalendarPermissions: async () => ({ granted: c.access !== "denied" }),
    getCalendars: async () => [{ id: "fake-calendar" }],
    listEvents: async () => { if (c.access === "read_error") throw new Error("simulated read failure"); return c.events.map((e, i) => ({ id: `ev-${i}`, ...e })); },
  };
  const warn = console.warn; console.warn = () => {};
  try {
    const w = await findFreeMealWindows(c.days, new Date(c.now));
    return w.map((x) => ({ start: x.start.toISOString(), minutes: x.minutes, meal: x.meal as Win["meal"] }));
  } finally { console.warn = warn; }
}

