for (const [cause, cases] of [["all-day busy events are ignored", ALLDAY_BUSY_IGNORED], ["first >= 20-min gap wins over a longer later gap", SHORT_FIRST_GAP]] as const) {
  describe(`calendar regression: ${cause}`, () => {
    for (const c of cases) {
      test(`${c.id} (${c.tz})`, async () => {
        assert.deepEqual(await run(c), c.expected);
      });
    }
  });
}

describe("calendar regression: controls", () => {
  for (const c of CONTROLS) {
    test(`${c.id} (${c.tz})`, async () => {
      assert.deepEqual(await run(c), c.expected);
    });
  }
});
